import { MESSAGES_PER_PAGE } from '@/constants'
import {
	GetProjectGroupRevisionContentUpdateDocument,
	GetProjectGroupRevisionContentUpdateSubscription,
	GetProjectGroupRevisionContentUpdateSubscriptionVariables,
	GetProjectGroupRevisionsForChatDocument,
	GetProjectGroupRevisionsForChatQuery,
	GetProjectGroupRevisionsForChatQueryVariables,
	ProjectGroupRevisionsCreatedDocument,
	ProjectGroupRevisionsCreatedSubscription,
	ProjectGroupRevisionsCreatedSubscriptionVariables,
	useProjectGroupRevisionForChatByIdLazyQuery
} from '@/generated/graphql'
import { useApolloClient } from '@apollo/client'
import { noop } from 'lodash'
import { useEffect } from 'react'
import { create } from 'zustand'
import { isStatusIndicatingRevisionIsBuilding } from '../utils/project-revision'
import { useChatStore } from '../store/chatStore'
import { socketEmitter } from '@/utils/apollo/socket'

export const useRevisionSubStore = create<{
	revisionIdsToSubscribe: Set<{ revisionId: string; threadId: string | null }>
	addRevisionId: (args: { revisionId: string; threadId: string | null }) => void
	removeByRevisionId: (args: { revisionId: string }) => void
	clear: () => void
}>((set) => ({
	revisionIdsToSubscribe: new Set(),
	removeByRevisionId: ({ revisionId: id }) =>
		set((state) => {
			const newSet = new Set(state.revisionIdsToSubscribe)
			for (const item of newSet) {
				if (item.revisionId === id) {
					newSet.delete(item)
				}
			}
			return { revisionIdsToSubscribe: newSet }
		}),
	addRevisionId: ({ revisionId: id, threadId }) =>
		set((state) => {
			const newSet = new Set(state.revisionIdsToSubscribe)
			newSet.add({ revisionId: id, threadId })
			return { revisionIdsToSubscribe: newSet }
		}),

	clear: () => set({ revisionIdsToSubscribe: new Set() })
}))

export const useSubscribeToRevisions = ({
	projectGroupId
}: {
	projectGroupId: string
}) => {
	const revisionIdsToSubscribeTo = Array.from(
		useRevisionSubStore((state) => state.revisionIdsToSubscribe)
	)
	const [getProjectGroupRevisionForChat] =
		useProjectGroupRevisionForChatByIdLazyQuery()
	const client = useApolloClient()
	const removeByRevisionId = useRevisionSubStore(
		(state) => state.removeByRevisionId
	)
	const setIsGenerating = useChatStore((state) => state.setIsGenerating)

	useEffect(() => {
		if (!projectGroupId) return
		const cache = client.cache
		const cleanups = revisionIdsToSubscribeTo.map(
			({ revisionId, threadId }) => {
				const observable = client.subscribe<
					GetProjectGroupRevisionContentUpdateSubscription,
					GetProjectGroupRevisionContentUpdateSubscriptionVariables
				>({
					query: GetProjectGroupRevisionContentUpdateDocument,
					variables: { id: revisionId }
				})
				const subscription = observable.subscribe({
					next: (subscriptionData) => {
						if (!subscriptionData.data) return

						const prev = cache.readQuery<
							GetProjectGroupRevisionsForChatQuery,
							GetProjectGroupRevisionsForChatQueryVariables
						>({
							query: GetProjectGroupRevisionsForChatDocument,
							variables: { projectGroupId, threadId, first: MESSAGES_PER_PAGE }
						})
						if (!prev) return noop

						const updatedRevision =
							subscriptionData.data.projectGroupRevisionContentUpdate
						const updatedRevisions =
							prev.projectGroupById?.revisions.edges.map((edge) =>
								edge.node.id === updatedRevision.id
									? {
											...edge,
											node: {
												...edge.node,
												...updatedRevision,
												__typename: 'ProjectGroupRevision' as const
											}
									  }
									: edge
							) ?? []
						const latestRevision = prev.projectGroupById.latestRevision
						if (latestRevision && updatedRevision.id === latestRevision.id) {
							const isGenerating = isStatusIndicatingRevisionIsBuilding(
								updatedRevision.status
							)
							setIsGenerating({ threadId, generating: isGenerating })
							if (!isGenerating) {
								removeByRevisionId({ revisionId: updatedRevision.id })
							}
						}
						cache.writeQuery<
							GetProjectGroupRevisionsForChatQuery,
							GetProjectGroupRevisionsForChatQueryVariables
						>({
							query: GetProjectGroupRevisionsForChatDocument,
							data: {
								projectGroupById: {
									...prev.projectGroupById,
									latestRevision:
										updatedRevision.id === latestRevision?.id
											? {
													...latestRevision,
													...updatedRevision,
													__typename: 'ProjectGroupRevision' as const
											  }
											: latestRevision,
									revisions: {
										...prev.projectGroupById.revisions,
										edges: updatedRevisions
									}
								}
							},
							variables: { projectGroupId, threadId }
						})
						return noop
					}
				})
				const cleanup = () => {
					subscription.unsubscribe()
				}
				return cleanup
			}
		)
		const observable = client.subscribe<
			ProjectGroupRevisionsCreatedSubscription,
			ProjectGroupRevisionsCreatedSubscriptionVariables
		>({
			query: ProjectGroupRevisionsCreatedDocument,
			variables: { id: projectGroupId }
		})
		const cleanups2 = revisionIdsToSubscribeTo.map(
			({ revisionId, threadId }) => {
				const subscription = observable.subscribe({
					next: (subscriptionData) => {
						const prev = client.readQuery<
							GetProjectGroupRevisionsForChatQuery,
							GetProjectGroupRevisionsForChatQueryVariables
						>({
							query: GetProjectGroupRevisionsForChatDocument,
							variables: {
								projectGroupId,
								threadId,
								first: MESSAGES_PER_PAGE
							}
						})
						if (!prev || !subscriptionData.data) return
						const { projectGroupRevisionsCreated } = subscriptionData.data
						if (
							projectGroupRevisionsCreated.id !== projectGroupId ||
							projectGroupRevisionsCreated.revisionIds.length === 0
						) {
							return prev
						}
						// only refetch if we do not have this revision, this indicates that i sent the revision
						const newRevisionIds =
							projectGroupRevisionsCreated.revisionIds.filter(
								(id) =>
									!prev.projectGroupById?.revisions?.edges.some(
										(edge) => edge.node.id === id
									)
							)
						if (newRevisionIds.length === 0) {
							return
						}
						client.query({
							query: GetProjectGroupRevisionsForChatDocument,
							variables: {
								projectGroupId,
								threadId,
								first: MESSAGES_PER_PAGE
							}
						})
						return
					}
				})
				const cleanup = () => {
					subscription.unsubscribe()
				}
				return cleanup
			}
		)
		const handleReconnect = async () => {
			if (!projectGroupId) return
			try {
				const [latestRevision, ...results] = await Promise.all([
					client.query<
						GetProjectGroupRevisionsForChatQuery,
						GetProjectGroupRevisionsForChatQueryVariables
					>({
						query: GetProjectGroupRevisionsForChatDocument,
						fetchPolicy: 'network-only',
						variables: {
							projectGroupId,
							threadId: null,
							first: MESSAGES_PER_PAGE
						}
					}),
					...revisionIdsToSubscribeTo
						.filter((id) => !id.revisionId.startsWith('optimistic-'))
						.map((id) =>
							getProjectGroupRevisionForChat({
								variables: { id: id.revisionId }
							})
						)
				])
				;[
					...results.map((r) => r.data?.projectGroupRevisionById),
					latestRevision.data.projectGroupById.latestRevision
				].forEach((revision) => {
					if (!revision) return
					const isGenerating = isStatusIndicatingRevisionIsBuilding(
						revision.status
					)
					const threadId = revision.thread?.id ?? null
					setIsGenerating({
						threadId,
						generating: isGenerating
					})
					if (!isGenerating) {
						removeByRevisionId({ revisionId: revision.id })
					}
				})
			} catch (error) {
				console.error(error)
			}
		}
		socketEmitter.on('reconnected', handleReconnect)

		return () => {
			socketEmitter.off('reconnected', handleReconnect)
			;[...cleanups, ...cleanups2].forEach((cleanup) => cleanup())
		}
	}, [
		client,
		getProjectGroupRevisionForChat,
		projectGroupId,
		removeByRevisionId,
		revisionIdsToSubscribeTo,
		setIsGenerating
	])
}
